 private static void reservationChecks(){var area=new AABB(ROOT).inflate(30);var channels=com.vandorlabs.redstone.ChannelList.EMPTY;var pending=NativeRampReservations.prepareClose(world,ROOT,channels,area,new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){return NativeRampReservations.Status.PENDING;}public boolean intersects(AABB b){throw new AssertionError("pending sweep inspected geometry");}});need(pending.status()==NativeRampReservations.Status.PENDING,"pending Canopy sweep is not READY/refused");var blocked=NativeRampReservations.prepareClose(world,ROOT,channels,area,new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){return NativeRampReservations.Status.READY;}public boolean intersects(AABB b){return b.intersects(new AABB(CHEST));}});need(blocked.status()==NativeRampReservations.Status.PENDING&&blocked.blockedCells().contains(CHEST)&&blocked.partnerRoots().contains(ROOT),"actual owned proxy physical collision blocks Canopy");var clear=NativeRampReservations.prepareClose(world,ROOT,channels,area,new NativeRampReservations.SweepQuery(){public NativeRampReservations.Status readiness(){return NativeRampReservations.Status.READY;}public boolean intersects(AABB b){return false;}});need(clear.status()==NativeRampReservations.Status.READY,"actual non-Moat physical proxies cleared by sweep");}
 private static void installNewerWrite(){NativeRampJournal.testFault=stage->{if(stage.equals("checkpoint-written")&&!newerWritten){newerWritten=true;world.setBlock(UNRELATED,Blocks.GOLD_BLOCK.defaultBlockState(),18);var chunk=world.getChunkSource().getChunkNow(ROOT.getX()>>4,ROOT.getZ()>>4);world.getChunkSource().chunkMap.write(new ChunkPos(ROOT),ChunkSerializer.write(world,chunk));}};}
 private static void finish(boolean abrupt){NativeRampJournal.testFault=null;System.out.println("[vandorlabs][ramp-journal] "+mode+" PASS checks="+checks+" abrupt="+abrupt);System.out.flush();var server=world.getServer();world=null;if(abrupt)Runtime.getRuntime().halt(0);else{server.saveEverything(true,true,true);server.halt(false);}}
